/// Returns true if this property is one of the animatable properties.
pub fn is_animatable(&self) -> bool {
    match self {
        Self::NonCustom(id) => id.is_animatable(),
        Self::Custom(_) => true,
    }
}

impl VariableDeclaration {
    fn substitute_variables<'cache>(
        &self,
        substitution_functions: &ComputedSubstitutionFunctions,
        stylist: &Stylist,
        computed_context: &computed::Context,
        shorthand_cache: &'cache mut ShorthandsWithPropertyReferencesCache,
        attribute_tracker: &mut AttributeTracker,
    ) -> Cow<'cache, PropertyDeclaration> {
        let longhand_id = self.id;
        let unparsed = &self.value;
        let invalid_at_computed_value_time = || {
            let keyword = if longhand_id.inherited() {
                CSSWideKeyword::Inherit
            } else {
                CSSWideKeyword::Initial
            };
            Cow::Owned(PropertyDeclaration::css_wide_keyword(longhand_id, keyword))
        };

        if computed_context
            .builder
            .invalid_non_custom_properties
            .contains(longhand_id)
        {
            return invalid_at_computed_value_time();
        }

        if let Some(shorthand_id) = unparsed.from_shorthand {
            let key = (shorthand_id, longhand_id);
            if shorthand_cache
                .get(&key)
                .is_some_and(|(source, _)| Arc::ptr_eq(source, unparsed))
            {
                // FIXME: This double lookup should be avoidable, but rustc
                // doesn't like that, see:
                //
                // https://github.com/rust-lang/rust/issues/82146
                return Cow::Borrowed(&shorthand_cache[&key].1);
            }
        }

        let property_id = unparsed.substitution_property_id(longhand_id);

        let SubstitutionResult { css, attr_taint } = match custom_properties::substitute(
            &unparsed.variable_value,
            Some(property_id),
            substitution_functions,
            stylist,
            computed_context,
            attribute_tracker,
        ) {
            Ok(css) => css,
            Err(..) => return invalid_at_computed_value_time(),
        };

        // As of this writing, only the base URL is used for property
        // values.
        //
        // NOTE(emilio): we intentionally pase `None` as the rule type here.
        // If something starts depending on it, it's probably a bug, since
        // it'd change how values are parsed depending on whether we're in a
        // @keyframes rule or not, for example... So think twice about
        // whether you want to do this!
        //
        // FIXME(emilio): ParsingMode is slightly fishy...
        let mut context = ParserContext::new(
            Origin::Author,
            &unparsed.variable_value.url_data,
            None,
            ParsingMode::DEFAULT,
            computed_context.quirks_mode,
            /* namespaces = */ Default::default(),
            None,
            None,
            attr_taint,
        );

        let mut input = Parser::new(&css);
        input.skip_whitespace();

        if let Ok(keyword) = input.try_parse(CSSWideKeyword::parse) {
            return Cow::Owned(PropertyDeclaration::css_wide_keyword(longhand_id, keyword));
        }

        let shorthand = match unparsed.from_shorthand {
            None => {
                return match context.with_property_declaration(property_id, |context| {
                    input.parse_entirely(|input| longhand_id.parse_value(context, input))
                }) {
                    Ok(decl) => Cow::Owned(decl),
                    Err(..) => invalid_at_computed_value_time(),
                };
            },
            Some(shorthand) => shorthand,

fn get_animated_properties(
    keyframes: &[Arc<Locked<Keyframe>>],
    guard: &SharedRwLockReadGuard,
) -> AnimatedProperties {
    let mut animated_properties = AnimatedProperties::default();

    // NB: declarations are already deduplicated, so we don't have to check for
    // it here.
    for keyframe in keyframes {
        let keyframe = keyframe.read_with(guard);
        let block = keyframe.block.read_with(guard);
        // CSS Animations spec clearly defines that properties with !important
        // in keyframe rules are invalid and ignored, but it's still ambiguous
        // whether we should drop the !important properties or retain the
        // properties when they are set via CSSOM. So we assume there might
        // be properties with !important in keyframe rules here.
        // See the spec issue https://github.com/w3c/csswg-drafts/issues/1824
        for declaration in block.normal_declaration_iter() {
            let declaration_id = declaration.id();

            if declaration_id == PropertyDeclarationId::Longhand(LonghandId::Display)
                && !crate::pref!("layout.css.display-animations.enabled")
            {
                continue;
            }

            if !declaration_id.is_animatable() {
                continue;
            }

            animated_properties.insert_animated_property(declaration_id);
            if AnimatedProperties::CAN_STOP_AFTER_FINDING_PROPERTY {
                return animated_properties;
            }
        }
    }

    animated_properties

/// A struct for a single specified registered custom property value that includes its original URL
/// data so the value can be uncomputed later.
#[derive(Clone, Debug, MallocSizeOf, ToCss, ToResolvedValue, ToShmem, ToTyped)]
#[typed(todo_derive_fields)]
pub struct Value<Component> {
    /// The registered custom property value.
    pub(crate) v: ValueInner<Component>,
    /// The URL data of the registered custom property from before it was computed. This is
    /// necessary to uncompute registered custom properties.
    #[css(skip)]
    url_data: UrlExtraData,
    /// Flag indicating whether this value is tainted by an attr().
    #[css(skip)]
    pub attr_tainted: bool,
}

impl<Component: ToComputedValue> ToComputedValue for Value<Component> {
    type ComputedValue = Value<Component::ComputedValue>;

    #[inline]
    fn to_computed_value(&self, context: &computed::Context) -> Self::ComputedValue {
        context.with_registered_value(|context| Value {
            v: self.v.to_computed_value(context),
            url_data: self.url_data.to_computed_value(context),
            attr_tainted: self.attr_tainted.to_computed_value(context),
        })
    }

    #[inline]
    fn from_computed_value(computed: &Self::ComputedValue) -> Self {
        Self {
            v: ToComputedValue::from_computed_value(&computed.v),
            url_data: ToComputedValue::from_computed_value(&computed.url_data),
            attr_tainted: ToComputedValue::from_computed_value(&computed.attr_tainted),
        }
    }
}

impl<Component: PartialEq> PartialEq for Value<Component> {
    // Ignore the url_data and tainting fields when comparing values for equality.
    fn eq(&self, other: &Self) -> bool {
        self.v == other.v
    }
}

impl<Component: Animate> Animate for Value<Component> {
    fn animate(&self, other: &Self, procedure: Procedure) -> Result<Self, ()> {
        let v = self.v.animate(&other.v, procedure)?;
        Ok(Value {
            v,
            url_data: self.url_data.clone(),
            attr_tainted: self.attr_tainted || other.attr_tainted,
        })
    }
}

impl<Component> Value<Component> {
    /// Creates a new registered custom property value.
    pub fn new(v: ValueInner<Component>, url_data: UrlExtraData) -> Self {
        Self {
            v,
            url_data,
            attr_tainted: Default::default(),
        }
    }

    /// Creates a new registered custom property value presumed to have universal syntax.
    pub fn universal(var: Arc<ComputedPropertyValue>) -> Self {
        let attr_tainted = var.is_attr_tainted();
        let url_data = var.url_data.clone();
        let v = ValueInner::Universal(var);
        Self {
            v,
            url_data,
            attr_tainted,
        }
    }

/// We use None in the value to represent a removed entry.
pub type OwnMap =
    IndexMap<Name, Option<ComputedRegisteredValue>, BuildHasherDefault<PrecomputedHasher>>;

static EMPTY: LazyLock<Arc<Inner>> = LazyLock::new(|| {
    Arc::new_leaked(Inner {
        own_properties: Default::default(),
        parent: None,
        len: 0,
        ancestor_count: 0,
    })
});

#[derive(Debug, Clone)]
struct Inner {
    own_properties: OwnMap,
    parent: Option<Arc<Inner>>,
    /// The number of custom properties with a value. Note that this is different from the sum of our
    /// own and our parent's length, since we might store duplicate entries.
    len: usize,
    /// The number of ancestors we have.
    ancestor_count: u8,
}

        }
    }
}

#[inline]
fn can_deduplicate_values(
    a: Option<&ComputedRegisteredValue>,
    b: Option<&ComputedRegisteredValue>,
) -> bool {
    match (a, b) {
        (Some(a), Some(b)) => {
            // TODO(emilio): Seems we should compare `url_data` as well? It doesn't seem to matter
            // much in practice since url values would be already-computed against the right base
            // URI here, I think...
            a == b && a.attr_tainted == b.attr_tainted
        },
        (None, None) => true,
        _ => false,
    }

}

fn is_empty(&self) -> bool {
    self.len == 0
}

fn len(&self) -> usize {
    self.len
}

fn get(&self, name: &Name) -> Option<&ComputedRegisteredValue> {
    if let Some(p) = self.own_properties.get(name) {
        return p.as_ref();
    }
    self.parent.as_ref()?.get(name)
}

fn insert(&mut self, name: &Name, value: Option<ComputedRegisteredValue>) {
    match (self.get(name).is_some(), value.is_some()) {
        (false, true) => self.len += 1,
        (true, false) => self.len -= 1,
        _ => {},
    }
    self.own_properties.insert(name.clone(), value);
}

/// Returns a given property value by name.
pub fn get(&self, name: &Name) -> Option<&ComputedRegisteredValue> {
    self.0.get(name)
}

fn do_insert(&mut self, name: &Name, value: Option<ComputedRegisteredValue>) {
    if let Some(inner) = Arc::get_mut(&mut self.0) {
        return inner.insert(name, value);
    }
    if can_deduplicate_values(self.get(name), value.as_ref()) {
        return;
    }
    if !self.0.should_expand_chain() {
        return Arc::make_mut(&mut self.0).insert(name, value);
    }
    let len = self.0.len;
    let ancestor_count = self.0.ancestor_count + 1;
    let mut new_inner = Inner {
        own_properties: Default::default(),
        // FIXME: Would be nice to avoid this clone.
        parent: Some(self.0.clone()),
        len,
        ancestor_count,
    };
    new_inner.insert(name, value);
    self.0 = Arc::new(new_inner);
}

/// Inserts an element in the map.
pub fn insert(&mut self, name: &Name, value: ComputedRegisteredValue) {
    self.do_insert(name, Some(value))
}

/// A value for a custom property is just a set of tokens.
///
/// We preserve the original CSS for serialization, and also the variable
/// references to other custom property names.
#[derive(Clone, Debug, MallocSizeOf, ToShmem)]
pub struct VariableValue {
    /// The raw CSS string.
    pub css: String,

    /// The url data of the stylesheet where this value came from.
    pub url_data: UrlExtraData,

    first_token_type: TokenSerializationType,
    last_token_type: TokenSerializationType,

    /// var(), env(), attr() or non-custom property (e.g. through `em`) references.
    pub references: References,

    /// Was this variable value attr tainted before. Used to keep attr tainting
    /// information when uncomputing a style that needs to be put back into the
    /// cascade.
    pub explicitly_attr_tainted: bool,
}

fn substitute_one_reference<'a>(
    css: &'a str,
    url_data: &UrlExtraData,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    reference: &'a SubstitutionFunctionReference,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SmallVec<[&'a Name; 8]>,
) -> Result<Substitution<'a>, ()> {
    let simple_attr_subst = |s: &str| {
        Some(Substitution::new(
            Cow::Owned(quoted_css_string(s)),
            TokenSerializationType::Nothing,
            TokenSerializationType::Nothing,
            /* attr_tainted */ true,
        ))
    };
    let substitution: Option<_> = match reference.substitution_kind {
        SubstitutionFunctionKind::Var => {
            let registration = stylist.get_custom_property_registration(&reference.name);
            match substitution_functions.get_var(registration, &reference.name) {
                None => None,
                // If the referenced value is itself still unresolved (i.e. it has references), we
                // are substituting against a partially-resolved map -- this happens while applying
                // a prioritary property in the middle of custom-property resolution. Resolve it
                // recursively, guarding against cycles (which the resolver will also remove, but it
                // may not have gotten to this variable yet).
                Some(v) => match v.as_universal() {
                    Some(u) if u.has_references() => {
                        if seen.contains(&&reference.name) {
                            // Cycle: the primary is guaranteed-invalid, so fall through to the
                            // fallback (if any), like any other invalid primary.
                            None
                        } else {
                            seen.push(&reference.name);
                            let result = substitute_internal(
                                u,
                                property_id,
                                substitution_functions,
                                stylist,
                                computed_context,
                                attribute_tracker,
                                seen,
                                /* attr_taint */ None,
                            );
                            seen.pop();
                            match result {
                                Ok(mut substitution) => {
                                    substitution.attr_tainted |= v.attr_tainted;
                                    Some(substitution)
                                },
                                // The primary couldn't be resolved (invalid); use the fallback.
                                Err(()) => None,
                            }
                        }
                    },
                    _ => Some(Substitution::from_value(
                        v.to_variable_value(),
                        v.attr_tainted,
                    )),
                },
            }
        },

/// Replace `var()`, `env()`, and `attr()` functions. Return `Err(..)` for invalid at computed time.
fn substitute_internal<'a>(
    variable_value: &'a VariableValue,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SmallVec<[&'a Name; 8]>,
    attr_taint: Option<&mut AttrTaint>,
) -> Result<Substitution<'a>, ()> {
    let mut substitution = do_substitute_chunk(
        &variable_value.css,
        /* start = */ 0,
        /* end = */ variable_value.css.len(),
        variable_value.first_token_type,
        variable_value.last_token_type,
        &variable_value.url_data,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        &variable_value.references.refs,
        attribute_tracker,
        seen,
        attr_taint,
    )?;
    substitution.attr_tainted |= variable_value.explicitly_attr_tainted;
    Ok(substitution)
}

/// Replace var(), env(), and attr() functions, returning the resulting CSS string.
pub fn substitute<'a>(
    variable_value: &'a VariableValue,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
) -> Result<SubstitutionResult<'a>, ()> {
    debug_assert!(variable_value.has_references());
    let mut attr_taint = AttrTaint::default();
    let v = substitute_internal(
        variable_value,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        attribute_tracker,
        &mut SmallVec::new(),
        Some(&mut attr_taint),
    )?;
    Ok(SubstitutionResult {
        css: v.css,
        attr_taint,
    })

fn substitute_variables_if_needed<'cache, 'decl>(
    &self,
    context: &mut computed::Context,
    shorthand_cache: &'cache mut ShorthandsWithPropertyReferencesCache,
    declaration: &'decl PropertyDeclaration,
    attribute_tracker: &mut AttributeTracker,
) -> Cow<'decl, PropertyDeclaration>
where
    'cache: 'decl,
{
    let declaration = match *declaration {
        PropertyDeclaration::WithVariables(ref declaration) => declaration,
        ref d => return Cow::Borrowed(d),
    };

    if !declaration.id.inherited() {
        context.rule_cache_conditions.borrow_mut().set_uncacheable();

        // NOTE(emilio): We only really need to add the `display` /
        // `content` flag if the CSS variable has not been specified on our
        // declarations, but we don't have that information at this point,
        // and it doesn't seem like an important enough optimization to
        // warrant it.
        if matches!(declaration.id, LonghandId::Display | LonghandId::Content) {
            context
                .builder
                .add_flags(ComputedValueFlags::DISPLAY_OR_CONTENT_DEPEND_ON_INHERITED_STYLE);
        }
    }

    debug_assert!(
        context.builder.stylist.is_some(),
        "Need a Stylist to substitute variables!"
    );
    declaration.substitute_variables(
        context.builder.substitution_functions(),
        context.builder.stylist.unwrap(),
        context,
        shorthand_cache,
        attribute_tracker,
    )
}

/// Cascade a given custom property declaration.
fn cascade_custom_property(
    &mut self,
    context: &mut computed::Context,
    declaration: &'a CustomDeclaration,
    priority: CascadePriority,
) {
    let CustomDeclaration {
        ref name,
        ref value,
    } = *declaration;

    if let Some(reverted) = self.reverted.custom.get(name)
        && !reverted.allows(&priority)
    {
        return;
    }

    if !(priority.flags() - context.included_cascade_flags).is_empty() {
        return;
    }

    let entry = match self.seen.custom.var.entry(name) {
        Entry::Occupied(..) => return,
        Entry::Vacant(v) => v,
    };

    let registration = self.stylist.get_custom_property_registration(name);
    let initial_values = self.stylist.get_custom_property_initial_values();
    if !Self::value_may_affect_style(context, name, registration, initial_values, value) {
        entry.insert(false);
        return;
    }

    let has_references = match value {
        CustomDeclarationValue::GuaranteedInvalid => false,
        CustomDeclarationValue::Unparsed(unparsed_value) => {
            // Non-custom dependency is really relevant for registered custom properties
            // that require computed value of such dependencies.
            unparsed_value
                .references
                .flags
                .intersects(ReferenceFlags::ATTR | ReferenceFlags::VAR)
                || !find_non_custom_references(
                    registration,
                    unparsed_value,
                    context.is_root_element(),
                )
                .is_empty()
        },
        // XXX This matches the previous behavior but I don't think it's fully sound. Parsed
        // values may have non-custom references, can't they? But also how do we get a parsed
        // value at all here?
        CustomDeclarationValue::Parsed(..) => false,
        // If we're a wide keyword we either get an initial value or an inherited one (no
        // references). Revert might have references, but we remove the `seen` entry, so it
        // doesn't matter.
        CustomDeclarationValue::CSSWideKeyword(..) => false,
    };
    self.may_have_custom_property_cycles |= has_references;
    entry.insert(has_references);

    match value {
        CustomDeclarationValue::GuaranteedInvalid => {
            context
                .builder
                .substitution_functions
                .remove_var(registration, name);
        },
        CustomDeclarationValue::Unparsed(unparsed_value) => {
            if !has_references {
                // If the variable value has no references to other properties, perform
                // substitution here instead of forcing a full traversal in `substitute_all`
                // afterwards.
                substitute_references_if_needed_and_apply(
                    name,
                    None,
                    unparsed_value,
                    self.stylist,
                    context,
                    // We just checked there are no attr dependencies.
                    &mut AttributeTracker::new_dummy(),
                );
                return;
            }
            let value = ComputedRegisteredValue::universal(Arc::clone(unparsed_value));
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        CustomDeclarationValue::Parsed(parsed_value) => {
            let value = parsed_value.to_computed_value(context);
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        CustomDeclarationValue::CSSWideKeyword(keyword) => match keyword.revert_kind() {
            Some(revert_kind) => {
                self.seen.custom.var.remove(name);
                if revert_kind != RevertKind::Rule {
                    self.reverted
                        .custom
                        .entry(name.clone())
                        .or_default()
                        .add(priority, revert_kind);
                }
            },
            None => match keyword {
                CSSWideKeyword::Initial => {
                    // For non-inherited custom properties, 'initial' was handled in value_may_affect_style.
                    debug_assert!(registration.inherits(), "Should've been handled earlier");
                    remove_and_insert_initial_value(
                        name,
                        registration,
                        initial_values,
                        &mut context.builder.substitution_functions,
                    );
                },
                CSSWideKeyword::Inherit => {
                    // For inherited custom properties, 'inherit' was handled in value_may_affect_style.
                    debug_assert!(!registration.inherits(), "Should've been handled earlier");
                    context
                        .style()
                        .add_flags(ComputedValueFlags::INHERITS_RESET_STYLE);
                    let inherited_value = context
                        .inherited_custom_properties()
                        .non_inherited
                        .get(name)
                        .cloned();
                    if let Some(inherited_value) = inherited_value {
                        context.builder.substitution_functions.insert_var(
                            registration,
                            name,
                            inherited_value,
                        );
                    } else {
                        context
                            .builder
                            .substitution_functions
                            .remove_var(registration, name);
                    }
                },
                // handled in value_may_affect_style or in the revert_kind branch above.
                CSSWideKeyword::Revert
                | CSSWideKeyword::RevertLayer
                | CSSWideKeyword::RevertRule
                | CSSWideKeyword::Unset => unreachable!(),
            },
        },
    }
}

fn process_animations(
    &self,
    context: &mut StyleContext<Self>,
    old_styles: &mut ElementStyles,
    new_styles: &mut ResolvedElementStyles,
    important_rules_changed: bool,
) {
    use crate::context::UpdateAnimationsTasks;

    let old_values = &old_styles.primary;
    if context.shared.traversal_flags.for_animation_only() && old_values.is_some() {
        return;
    }

    // Bug 868975: These steps should examine and update the visited styles
    // in addition to the unvisited styles.

    let mut tasks = UpdateAnimationsTasks::empty();

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_timeline_scope()
        },
        |old| {
            !old.get_ui()
                .timeline_scope_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::TIMELINE_SCOPES);
    }

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_scroll_timelines()
        },
        |old| {
            !old.get_ui()
                .scroll_timelines_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::SCROLL_TIMELINES);
    }

    if old_values.as_deref().map_or_else(
        || {
            new_styles
                .primary_style()
                .get_ui()
                .specifies_view_timelines()
        },
        |old| {
            !old.get_ui()
                .view_timelines_equals(new_styles.primary_style().get_ui())
        },
    ) {
        tasks.insert(UpdateAnimationsTasks::VIEW_TIMELINES);
    }

    if self.needs_animations_update(
        context,
        old_values.as_deref(),
        new_styles.primary_style(),
        /* pseudo_element = */ None,
    ) {
        tasks.insert(UpdateAnimationsTasks::CSS_ANIMATIONS);
        tasks.insert(UpdateAnimationsTasks::EFFECT_PROPERTIES);
    }

    let before_change_style =
        self.process_transitions(context, old_values.as_ref(), new_styles);
    if before_change_style.is_some() {
        tasks.insert(UpdateAnimationsTasks::CSS_TRANSITIONS);
    }

    if self.has_animations(context.shared) {
        tasks.insert(UpdateAnimationsTasks::EFFECT_PROPERTIES);
        if important_rules_changed {
            tasks.insert(UpdateAnimationsTasks::CASCADE_RESULTS);
        }
        if new_styles
            .primary_style()
            .is_display_property_changed_from_none(old_values.as_deref())
        {
            tasks.insert(UpdateAnimationsTasks::DISPLAY_CHANGED_FROM_NONE);
        }
    }

    if !tasks.is_empty() {
        let task = crate::context::SequentialTask::update_animations(
            *self,
            before_change_style,
            tasks,
        );
        context.thread_local.tasks.push(task);
    }

let StyleChange::Changed {
    reset_only,
    custom_properties_changed,
} = difference.change
else {
    return children_hint;
};

let new_container_name = new_values.get_container_name();
if new_container_name != old_values.get_container_name() {
    // If we're becoming or stopped to become a named container, we need to potentially
    // restyle children.
    children_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_NAMED_STYLE_CONTAINER;
} else if custom_properties_changed {
    // Custom property changes affect style queries. How specifically depends on whether
    // we're a named container (more expensive, need to check the subtree) or not.
    children_hint |= if !new_container_name.is_none() {
        RestyleHint::RESTYLE_IF_AFFECTED_BY_NAMED_STYLE_CONTAINER
    } else {
        RestyleHint::RESTYLE_IF_AFFECTED_BY_STYLE_QUERIES
    };
}

if reset_only {
    // If only reset properties changed, we _might_ need to unconditionally restyle, but
    // most likely we can get away with stopping the cascade at the next level, if our
    // children don't inherit reset properties.
    children_hint |=
        if need_to_unconditionally_recascade_for_reset_change(old_values, new_values) {
            RestyleHint::RECASCADE_SELF
        } else {
            RestyleHint::RECASCADE_SELF_IF_INHERIT_RESET_STYLE
        };
} else {
    // If inherited properties changed, we need to cascade our children.
    children_hint |= RestyleHint::RECASCADE_SELF;
}

children_hint

fn finish_restyle(
    &self,
    context: &mut StyleContext<Self>,
    data: &mut ElementData,
    mut new_styles: ResolvedElementStyles,
    important_rules_changed: bool,
) -> RestyleHint {
    self.process_animations(
        context,
        &mut data.styles,
        &mut new_styles,
        important_rules_changed,
    );

    // First of all, update the styles.
    let old_styles = data.set_styles(new_styles);

let device = context.shared.stylist.device();
let new_font_size = new_primary_style.get_font().slow_clone_font_size();
let new_container_type = *new_primary_style.get_container_type();

let old_style = old_styles.primary.as_ref();
let old_font_size = old_style.map(|s| s.get_font().slow_clone_font_size());
let font_size_changed = old_font_size.is_none_or(|fs| fs != new_font_size);

let line_height_likely_changed =
    font_size_changed || Self::line_height_likely_changed(old_style, new_primary_style);

// Update root font-relative units. If any of these unit values changed
// since last time, ensure that we recascade the entire tree.
if is_root {
    debug_assert!(self.owner_doc_matches_for_testing(device));
    device.set_root_style(new_primary_style);

    // Update root font size for rem units
    if font_size_changed {
        let size = new_font_size.computed_size();
        device.set_root_font_size(new_primary_style.effective_zoom.unzoom(size.px()));
    }

    // Update root line height for rlh units
    if line_height_likely_changed {
        let new_line_height = device
            .calc_line_height(
                new_primary_style.get_font(),
                new_primary_style.writing_mode,
                None,
            )
            .0;
        device.set_root_line_height(
            new_primary_style
                .effective_zoom
                .unzoom(new_line_height.px()),
        );
    }

    // Update root font metrics for rcap, rch, rex, ric units. Since querying
    // font metrics can be an expensive call, they are only updated if these
    // units are used in the document.
    if device.used_root_font_metrics() && device.update_root_font_metrics() {
        child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
    }
}

if font_size_changed || line_height_likely_changed {
    child_restyle_hint |= RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
}

    /// We need to recascade with some replacement rule, such as the style
    /// attribute, or animation rules.
    CascadeWithReplacements(RestyleHint),
    /// We only need to recascade, for example, because only inherited
    /// properties in the parent changed.
    CascadeOnly,
}

fn needs_to_match_self(hint: RestyleHint, style: &ComputedValues) -> bool {
    if hint.intersects(RestyleHint::RESTYLE_SELF) {
        return true;
    }
    if hint.intersects(RestyleHint::RESTYLE_SELF_IF_PSEUDO) && style.is_pseudo_style() {
        return true;
    }
    if hint.intersects(RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT)
        && style
            .flags
            .intersects(ComputedValueFlags::USES_FONT_OR_WM_RELATIVE_UNITS_ON_CONTAINER_QUERIES)
    {
        return true;
    }
    hint.intersects(
        RestyleHint::RESTYLE_IF_AFFECTED_BY_STYLE_QUERIES
            | RestyleHint::RESTYLE_IF_AFFECTED_BY_NAMED_STYLE_CONTAINER,
    ) && style
        .flags
        .intersects(ComputedValueFlags::DEPENDS_ON_CONTAINER_STYLE_QUERY)
}

fn needs_to_recascade_self(
    hint: RestyleHint,
    style: &ComputedValues,
    has_animations: bool,
) -> bool {
    if hint.intersects(RestyleHint::RECASCADE_SELF) {
        return true;
    }
    if hint.intersects(RestyleHint::RECASCADE_SELF_IF_INHERIT_RESET_STYLE)
        && style
            .flags
            .contains(ComputedValueFlags::INHERITS_RESET_STYLE)
    {
        return true;
    }
    if hint.intersects(RestyleHint::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT)
        && (has_animations
            || style
                .flags
                .contains(ComputedValueFlags::USES_FONT_OR_WM_RELATIVE_UNITS))
    {
        return true;
    }
    false

pub fn restyle_kind(
    &self,
    shared_context: &SharedStyleContext,
    has_animations: bool,
) -> Option<RestyleKind> {
    let style = match self.styles.primary {
        Some(ref s) => s,
        None => return Some(RestyleKind::MatchAndCascade),
    };

    if shared_context.traversal_flags.for_animation_only() {
        return self.restyle_kind_for_animation(shared_context);
    }

    let hint = self.hint;
    if hint.is_empty() {
        return None;
    }

    if needs_to_match_self(hint, style) {
        return Some(RestyleKind::MatchAndCascade);
    }

    if hint.has_replacements() {
        debug_assert!(
            !hint.has_animation_hint(),
            "Animation only restyle hint should have already processed"
        );
        return Some(RestyleKind::CascadeWithReplacements(
            hint & RestyleHint::replacements(),
        ));
    }

    if needs_to_recascade_self(hint, style, has_animations) {
        return Some(RestyleKind::CascadeOnly);
    }

    None
}

/// Returns the kind of restyling for animation-only restyle.
fn restyle_kind_for_animation(
    &self,
    shared_context: &SharedStyleContext,
) -> Option<RestyleKind> {
    debug_assert!(shared_context.traversal_flags.for_animation_only());
    debug_assert!(self.has_styles());

    // FIXME: We should ideally restyle here, but it is a hack to work around our weird
    // animation-only traversal stuff: If we're display: none and the rules we could
    // match could change, we consider our style up-to-date. This is because re-cascading with
    // and old style doesn't guarantee returning the correct animation style (that's
    // bug 1393323). So if our display changed, and it changed from display: none, we would
    // incorrectly forget about it and wouldn't be able to correctly style our descendants
    // later.
    // XXX Figure out if this still makes sense.
    let hint = self.hint;
    if self.styles.is_display_none() && hint.intersects(RestyleHint::RESTYLE_SELF) {
        return None;
    }

    let style = self.styles.primary();
    // Return either CascadeWithReplacements or CascadeOnly in case of animation-only restyle.
    // I.e. animation-only restyle never does selector matching.
    if hint.has_animation_hint() {
        return Some(RestyleKind::CascadeWithReplacements(
            hint & RestyleHint::for_animations(),
        ));
    }

    if needs_to_recascade_self(hint, style, false) {
        return Some(RestyleKind::CascadeOnly);
    }
    None
}

pub fn propagate(&mut self, traversal_flags: &TraversalFlags) -> Self {
    // In the middle of an animation only restyle, we don't need to
    // propagate any restyle hints, and we need to remove ourselves.
    if traversal_flags.for_animation_only() {
        self.remove_animation_hints();
        return Self::empty();
    }

    debug_assert!(
        !self.has_animation_hint(),
        "There should not be any animation restyle hints \
         during normal traversal"
    );

    // Else we should clear ourselves, and return the propagated hint.
    std::mem::take(self).propagate_for_non_animation_restyle()
}

/// Returns a new `RestyleHint` appropriate for children of the current element.
fn propagate_for_non_animation_restyle(&self) -> Self {
    if self.contains(RestyleHint::RESTYLE_DESCENDANTS) {
        return Self::restyle_subtree();
    }
    let mut result = Self::empty();
    if self.contains(Self::RESTYLE_PSEUDOS) {
        result |= Self::RESTYLE_SELF_IF_PSEUDO;
    }
    if self.contains(Self::RECASCADE_DESCENDANTS) {
        result |= Self::recascade_subtree();
    }
    if self.contains(Self::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT) {
        result |= Self::RESTYLE_IF_AFFECTED_BY_WM_OR_ANCESTOR_FONT;
    }
    if self.contains(Self::RESTYLE_CHILD_IF_AFFECTED_BY_STYLE_QUERIES) {
        result |= Self::RESTYLE_IF_AFFECTED_BY_STYLE_QUERIES;
    }
    if self.contains(Self::RESTYLE_IF_AFFECTED_BY_NAMED_STYLE_CONTAINER) {
        // We may need to restyle further down the tree if rules are
        // declared for a named container.
        // e.g @container my-name {#b {...}}
        // and <div id=a> <div> <div id=b> </div> </div> </div>
        // If a toggles `container-name: my-name` the rules for #b
        // also invalidate. This is why we need one hint for unnamed
        // container and one for named containers.
        result |= Self::RESTYLE_IF_AFFECTED_BY_NAMED_STYLE_CONTAINER;
    }
    result

void Gecko_UpdateAnimations(const Element* aElement,
                            const ComputedStyle* aOldComputedData,
                            const ComputedStyle* aComputedData,
                            UpdateAnimationsTasks aTasks) {
  MOZ_ASSERT(NS_IsMainThread());
  MOZ_ASSERT(aElement);

  if (!aElement->IsInComposedDoc()) {
    return;
  }

  nsPresContext* presContext = nsContentUtils::GetContextForContent(aElement);
  if (!presContext || !presContext->IsDynamic()) {
    return;
  }

  nsAutoAnimationMutationBatch mb(aElement->OwnerDoc());

  const auto [element, pseudoRequest] =
      AnimationUtils::GetElementPseudoPair(aElement);

  // Handle timeline scopes first, because our own scroll/view-linked animations
  // may be affected.
  if (aTasks & UpdateAnimationsTasks::TimelineScopes) {
    presContext->TimelineManager()->UpdateTimelineScopes(element,
                                                         aComputedData);
    // We could try to limit the impact here, at least for changes involving not
    // `all`. However, defer any such optimization until after bug 2024012.
    presContext->AnimationManager()->UpdateAllNamedTimelineAnimations();
  }

  // Handle scroll/view timelines first because CSS animations may refer to the
  // timeline defined by itself.
  if (aTasks & UpdateAnimationsTasks::ScrollTimelines) {
    const auto affected = presContext->TimelineManager()->UpdateTimelines(
        const_cast<Element*>(element), pseudoRequest, aComputedData,
        TimelineManager::ProgressTimelineType::Scroll);
    presContext->AnimationManager()->UpdateNamedTimelineAnimations(affected);
  }

  if (aTasks & UpdateAnimationsTasks::ViewTimelines) {
    const auto affected = presContext->TimelineManager()->UpdateTimelines(
        const_cast<Element*>(element), pseudoRequest, aComputedData,
        TimelineManager::ProgressTimelineType::View);
    presContext->AnimationManager()->UpdateNamedTimelineAnimations(affected);
  }

  if (aTasks & UpdateAnimationsTasks::CSSAnimations) {
    presContext->AnimationManager()->UpdateAnimations(
        const_cast<Element*>(element), pseudoRequest, aComputedData);
  }

  // aComputedData might be nullptr if the target element is now in a
  // display:none subtree. We still call Gecko_UpdateAnimations in this case
  // because we need to stop CSS animations in the display:none subtree.
  // However, we don't need to update transitions since they are stopped by
  // RestyleManager::AnimationsWithDestroyedFrame so we just return early
  // here.
  if (!aComputedData) {
    return;
  }

  if (aTasks & UpdateAnimationsTasks::CSSTransitions) {
    MOZ_ASSERT(aOldComputedData);
    presContext->TransitionManager()->UpdateTransitions(
        const_cast<Element*>(element), pseudoRequest, *aOldComputedData,
        *aComputedData);
  }

  if (aTasks & UpdateAnimationsTasks::EffectProperties) {
    presContext->EffectCompositor()->UpdateEffectProperties(
        aComputedData, const_cast<Element*>(element), pseudoRequest);
  }

  if (aTasks & UpdateAnimationsTasks::CascadeResults) {
    EffectSet* effectSet = EffectSet::Get(element, pseudoRequest);
    // CSS animations/transitions might have been destroyed as part of the above
    // steps so before updating cascade results, we check if there are still any
    // animations to update.
    if (effectSet) {
      // We call UpdateCascadeResults directly (intead of
      // MaybeUpdateCascadeResults) since we know for sure that the cascade has
      // changed, but we were unable to call MarkCascadeUpdated when we noticed
      // it since we avoid mutating state as part of the Servo parallel
      // traversal.
      presContext->EffectCompositor()->UpdateCascadeResults(
          *effectSet, const_cast<Element*>(element), pseudoRequest);
    }
  }

  if (aTasks & UpdateAnimationsTasks::DisplayChangedFromNone) {
    presContext->EffectCompositor()->RequestRestyle(
        const_cast<Element*>(element), pseudoRequest,
        EffectCompositor::RestyleType::Standard,
        EffectCompositor::CascadeLevel::Animations);
  }
}

nsTArray<RefPtr<const nsAtom>> TimelineManager::UpdateTimelines(
    Element* aElement, const PseudoStyleRequest& aPseudoRequest,
    const ComputedStyle* aComputedStyle, ProgressTimelineType aType) {
  MOZ_ASSERT(
      aElement->IsInComposedDoc(),
      "No need to update timelines that are not attached to the document tree");

  // If we are in a display:none subtree we will have no computed values.
  // However, if we are on the root of display:none subtree, the computed values
  // might not have been cleared yet. In either case, since CSS animations
  // should not run in display:none subtrees, so we don't need timeline, either.
  const bool shouldDestroyTimelines =
      !aComputedStyle ||
      aComputedStyle->StyleDisplay()->mDisplay == StyleDisplay::None;

  switch (aType) {
    case ProgressTimelineType::Scroll:
      if (shouldDestroyTimelines) {
        return TryDestroyTimeline<ScrollTimeline>(aElement, aPseudoRequest,
                                                  mScrollTimelineNameMap);
      }
      return DoUpdateTimelines<ScrollTimeline>(
          mPresContext, aElement, aPseudoRequest,
          aComputedStyle->StyleUIReset(), mScrollTimelineNameMap);

    case ProgressTimelineType::View:

nsTArray<RefPtr<const nsAtom>> TimelineManager::DoUpdateTimelines(
    nsPresContext* aPresContext, Element* aElement,
    const PseudoStyleRequest& aPseudoRequest, const nsStyleUIReset* aUIReset,
    TimelineNameMap<TimelineType>& aTimelineNameMap) {
  using Builder = TimelineBuilder<TimelineType>;
  auto* collection =
      TimelineCollection<TimelineType>::Get(aElement, aPseudoRequest);
  if (!collection && Builder::NameCount(aUIReset) == 1 &&
      Builder::Name(aUIReset, 0).mName == nsGkAtoms::_empty) {
    return {};
  }

  // We create a new timeline list based on its computed style and the existing
  // timelines.
  auto newTimelines = BuildTimelines<TimelineType>(
      aPresContext, aElement, aPseudoRequest, aUIReset, collection);

  if (newTimelines.IsEmpty()) {
    nsTArray<RefPtr<const nsAtom>> result{
        collection ? collection->Timelines().Count() : 0};
    if (collection) {
      for (const auto& name : collection->Timelines().Keys()) {
        result.AppendElement(name);
        RemoveTimelineTargetByName(name, aElement, aPseudoRequest,
                                   aTimelineNameMap);
      }
      collection->Destroy();
    }
    return result;
  }

  if (!collection) {
    collection =
        &EnsureTimelineCollection<TimelineType>(*aElement, aPseudoRequest);
    if (!collection->isInList()) {
      AddTimelineCollection(collection);
    }
  }

  nsTArray<RefPtr<const nsAtom>> result{collection->Timelines().Count() +
                                        newTimelines.Count()};
  for (const auto& removed : collection->Timelines().Keys()) {
    result.AppendElement(removed);
    RemoveTimelineTargetByName(removed, aElement, aPseudoRequest,
                               aTimelineNameMap);
  }

  // Replace unused timeline with new ones.
  collection->Swap(newTimelines);

  for (auto addedOrExisting = collection->Timelines().ConstIter();
       !addedOrExisting.Done(); addedOrExisting.Next()) {
    auto& targets = aTimelineNameMap.LookupOrInsert(addedOrExisting.Key(),
                                                    Timelines<TimelineType>{});
    auto foundIt = FindInTimelineTargets(targets, aElement, aPseudoRequest);
    if (foundIt != targets.cend()) {
#ifdef DEBUG
      EnsureNoTimelineTarget<TimelineType>(foundIt + 1, targets.cend(),
                                           aElement, aPseudoRequest);
#endif
      continue;
    }
    result.AppendElement(addedOrExisting.Key());
    const auto& entry = addedOrExisting.Data();
    const auto target = entry.mTimeline->TimelineTarget();
    const auto* element =
        target.mElement->GetPseudoElement(target.mPseudoRequest);
    struct ElementComparator {
      const Element* mElement;
      int32_t operator()(const TimelineEntry<TimelineType>& aOther) const {
        const auto target = aOther.mTimeline->TimelineTarget();
        const auto* element =
            target.mElement->GetPseudoElement(target.mPseudoRequest);
        return nsContentUtils::CompareTreePosition<
            TreeKind::ShadowIncludingDOM>(mElement, element, nullptr);
      }
    };

    ElementComparator cmp{element};
    auto matchOrInsertionIdx = targets.Length();
    if (BinarySearchIf(targets, 0, targets.Length(), cmp,
                       &matchOrInsertionIdx)) {
      if (MOZ_UNLIKELY(targets.ElementAt(matchOrInsertionIdx).mTimeline ==
                       entry.mTimeline)) {
        MOZ_ASSERT_UNREACHABLE("Duplicate entry");
        continue;
      }
    }

    targets.InsertElementAt(matchOrInsertionIdx, entry);
  }

  // FIXME: Bug 1774060. We may have to restyle the animations which use the
  // dropped timelines. Or rely on restyling the subtree and the following
  // siblings when mutating {scroll|view}-timeline-name.
  return result;

pub struct ComputedCustomProperties {
    /// Map for custom properties with inherit flag set, including non-registered
    /// ones.
    pub inherited: CustomPropertiesMap,
    /// Map for custom properties with inherit flag unset.
    pub non_inherited: CustomPropertiesMap,
}

impl ComputedCustomProperties {
    /// Return whether the inherited and non_inherited maps are none.
    pub fn is_empty(&self) -> bool {
        self.inherited.is_empty() && self.non_inherited.is_empty()
    }

    /// Return the name and value of the property at specified index, if any.
    pub fn property_at(&self, index: usize) -> Option<(&Name, &Option<ComputedRegisteredValue>)> {
        // Just expose the custom property items from custom_properties.inherited, followed
        // by custom property items from custom_properties.non_inherited.
        self.inherited
            .get_index(index)
            .or_else(|| self.non_inherited.get_index(index - self.inherited.len()))
    }

    /// Insert a custom property in the corresponding inherited/non_inherited
    /// map, depending on whether the inherit flag is set or unset.
    pub fn insert(
        &mut self,
        registration: &PropertyDescriptors,
        name: &Name,
        value: ComputedRegisteredValue,
    ) {
        self.map_mut(registration).insert(name, value)
    }

    /// Remove a custom property from the corresponding inherited/non_inherited
    /// map, depending on whether the inherit flag is set or unset.
    pub fn remove(&mut self, registration: &PropertyDescriptors, name: &Name) {
        self.map_mut(registration).remove(name);
    }

    /// Shrink the capacity of the inherited maps as much as possible.
    pub fn shrink_to_fit(&mut self) {
        self.inherited.shrink_to_fit();
        self.non_inherited.shrink_to_fit();
    }

    fn map_mut(&mut self, registration: &PropertyDescriptors) -> &mut CustomPropertiesMap {
        if registration.inherits() {
            &mut self.inherited
        } else {
            &mut self.non_inherited
        }
    }

    /// Returns the relevant custom property value given a registration.
    pub fn get(
        &self,
        registration: &PropertyDescriptors,
        name: &Name,
    ) -> Option<&ComputedRegisteredValue> {
        if registration.inherits() {
            self.inherited.get(name)
        } else {
            self.non_inherited.get(name)
        }
    }

    /// Returns a property just by the name. Slightly less efficient than get(), if you already have
    /// a custom registration handy, thus the longer name.
    pub fn get_for_cssom(&self, name: &Name) -> Option<&ComputedRegisteredValue> {
        self.inherited
            .get(name)
            .or_else(|| self.non_inherited.get(name))
    }
}

/// A wrapper map that encapsulates both the custom properties and attributes
/// for a given element.
#[repr(C)]
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ComputedSubstitutionFunctions {
    /// The applicable custom properties (includes inherited and non-inherited).
    pub custom_properties: ComputedCustomProperties,
    /// The applicable DOM attributes.
    pub attributes: PrecomputedHashMap<Namespace, OwnMap>,
}

impl ComputedSubstitutionFunctions {
    /// Creates a substitution function map from optional custom properties
    /// and DOM attributes.
    #[inline(always)]
    pub fn new(
        custom_properties: Option<ComputedCustomProperties>,
        attributes: Option<PrecomputedHashMap<Namespace, OwnMap>>,
    ) -> Self {
        Self {
            custom_properties: custom_properties.unwrap_or_default(),
            attributes: attributes.unwrap_or_default(),
        }
    }

    #[inline(always)]
    pub(crate) fn insert_var(
        &mut self,
        registration: &PropertyDescriptors,
        name: &Name,
        value: ComputedRegisteredValue,
    ) {
        self.custom_properties.insert(registration, name, value);
    }

    /// Store a computed attribute value by its expanded name.
    #[inline(always)]
    pub fn insert_attr(
        &mut self,
        name: &Name,
        namespace: &Namespace,
        value: ComputedRegisteredValue,
    ) {
        self.attributes
            .entry(namespace.clone())
            .or_default()
            .insert(name.clone(), Some(value));
    }

    #[inline(always)]
    pub(crate) fn remove_var(&mut self, registration: &PropertyDescriptors, name: &Name) {
        self.custom_properties.remove(registration, name);
    }

    #[inline(always)]
    pub(crate) fn remove_attr(&mut self, name: &Name, namespace: &Namespace) {
        self.attributes
            .entry(namespace.clone())
            .or_default()
            .insert(name.clone(), None);
    }

    #[inline(always)]
    pub(crate) fn get_var(
        &self,
        registration: &PropertyDescriptors,
        name: &Name,
    ) -> Option<&ComputedRegisteredValue> {
        self.custom_properties.get(registration, name)
    }
